-- Use the installed Tier 4 global tokens and their existing client extended costs.
CREATE TEMPORARY TABLE `_coa_karazhan_tier4_tokens` (
    `entry` INT UNSIGNED PRIMARY KEY,
    `item_level` SMALLINT UNSIGNED NOT NULL,
    `description` VARCHAR(128) NOT NULL
) ENGINE=InnoDB;

DELETE FROM `_coa_karazhan_tier4_tokens`;

START TRANSACTION;

UPDATE `item_template` AS `item`
JOIN `_coa_karazhan_tier4_tokens` AS `token` ON `token`.`entry` = `item`.`entry`
SET `item`.`ItemLevel` = `token`.`item_level`, `item`.`RequiredLevel` = 60,
    `item`.`description` = `token`.`description`;

DELETE FROM `npc_vendor` WHERE `entry` IN (91000014, 91000015, 91000016, 91000017);

COMMIT;

DROP TEMPORARY TABLE `_coa_karazhan_tier4_tokens`;
